export function a() {
  // Large body: this must survive because the namespace object escapes.
  const parts = ['alpha', 'bravo', 'charlie', 'delta', 'echo', 'foxtrot'];
  const woven = parts
    .map((p, i) => `${i}:${p}`)
    .filter((s) => !s.includes('zulu'))
    .join('/');
  const checksum = woven.split('').reduce((acc, ch) => acc + ch.charCodeAt(0), 0);
  return `a:${checksum}`;
}

export function b() {
  // Large body: never referenced statically by the app, but the escaped
  // namespace means a sound analyzer cannot prove it unreachable.
  const grid = [];
  for (let r = 0; r < 8; r++) {
    const row = [];
    for (let c = 0; c < 8; c++) {
      row.push((r * 8 + c) % 7);
    }
    grid.push(row.join(''));
  }
  const folded = grid.reverse().join('-');
  return `b:${folded.length}:${folded.slice(0, 12)}`;
}
